INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('21c64a3f-f92b-5108-86e0-e6d30c4481d0','ebe8e234-e065-5b9d-b9ba-b09cccbc3ec6','자산 등록과 관리번호','가상 자산관리 시스템의 자산 담당자는 노트북, 모니터, 휴대전화에 고유한 자산번호를 부여한다. 자산번호와 제조사 일련번호는 중복될 수 없다. 신규 등록 시 자산 상태는 AVAILABLE(대여 가능)이다. 분실 신고된 장비나 폐기된 장비를 신규 재고로 다시 등록하지 않는다. 구매일, 장비 종류, 관리 부서, 일련번호는 필수 입력이다.','{"documentId": "ebe8e234-e065-5b9d-b9ba-b09cccbc3ec6", "chunkId": "21c64a3f-f92b-5108-86e0-e6d30c4481d0", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "자산 등록과 관리번호", "relatedApis": ["POST /assets"]}'::jsonb,'[-0.014192868955433369, -0.029202083125710487, -0.04664021357893944, 0.034705545753240585, -0.03394359350204468, -0.00571361742913723, 0.011924156919121742, 0.033317942172288895, 0.010527169331908226, -0.008973738178610802, 0.012501521967351437, 0.0005422636168077588, -0.025633668527007103, 0.021761193871498108, 0.030445042997598648, -0.022104760631918907, 0.003214245894923806, -0.01767679676413536, -0.024356894195079803, -0.022331805899739265, -0.04508090391755104, -0.02795465476810932, 0.017635269090533257, 0.030778538435697556, -0.0035711158998310566, 0.030006729066371918, -0.05303220450878143, -0.013722669333219528, 0.06565654277801514, 0.04132351651787758, -0.0011110337218269706, -0.006276217754930258, -0.021161729469895363, -0.010130953043699265, -0.008312663063406944, 0.0034022571053355932, -0.04054761305451393, -0.02506137266755104, -0.029501713812351227, 0.03950526565313339, -0.046028368175029755, 0.017916275188326836, -0.015211066231131554, -0.039899855852127075, 0.0048520369455218315, -0.01616567187011242, -0.004451839718967676, -0.027031853795051575, -0.05455456301569939, -0.051139988005161285, -0.005521109793335199, 1.3649260836245958e-05, 0.05705435946583748, -0.009670685045421124, 0.004664960317313671, 0.07463778555393219, -0.02273656614124775, -0.010624160058796406, -0.05027993768453598, 0.009234093