INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('3e8c8b89-7feb-5089-ad27-a092afa3a27e','ebe8e234-e065-5b9d-b9ba-b09cccbc3ec6','대여 가능한 재고 판정','임직원에게 지급할 수 있는 재고는 자산 상태가 AVAILABLE이고 활성 대여 기록이 없는 장비다. RESERVED(예약), ON_LOAN(대여 중), MAINTENANCE(수리 중), LOST(분실), RETIRED(폐기) 상태는 대여할 수 없다. 예약은 승인 완료부터 실물 지급까지 유효하다. 대여 화면의 재고 조회 결과만 신뢰하지 않고 승인 트랜잭션에서 최신 상태를 다시 확인한다.','{"documentId": "ebe8e234-e065-5b9d-b9ba-b09cccbc3ec6", "chunkId": "3e8c8b89-7feb-5089-ad27-a092afa3a27e", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "대여 가능한 재고 판정", "relatedApis": ["GET /assets", "POST /loans/{loanId}/approve"]}'::jsonb,'[-0.014811323955655098, 0.02072141319513321, -0.024147452786564827, 0.04068217799067497, -0.021576102823019028, -0.018653543666005135, -0.002523340517655015, 0.05531710386276245, -0.005950260441750288, -0.0039610713720321655, 0.027245517820119858, 0.006327288690954447, -0.018705040216445923, 0.037189412862062454, 0.040902938693761826, 0.01792244240641594, 0.013247562572360039, 0.0014991607749834657, -0.03760579228401184, 0.0021309261210262775, 0.00451046135276556, 0.0037559925112873316, 0.01776105910539627, 0.04746011272072792, -0.013558724895119667, -0.015685372054576874, -0.010377327911555767, 0.01843770407140255, 0.06384923309087753, 0.05934150889515877, -0.009134581312537193, -0.026760250329971313, -0.019373465329408646, -0.03089308924973011, -0.014144225046038628, -0.020247045904397964, -0.035994723439216614, 0.0013795156264677644, -0.03475644811987877, 0.05157363787293434, -0.045626021921634674, -0.012960433959960938, -0.013550207950174809, -0.027890756726264954, 0.005064798053354025, -0.010214176960289478, -0.02995302714407444, -0.021697672083973885, -0.042232442647218704, -0.013855629600584507, -0.02933698520064354, 0.007786161731928587, 0.06411522626876831, -0.011708363890647888, 0.00507553294301033, 0.07852207124233246, 0.0024202398490160704, 