INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('dd4f1c1d-2846-5913-aad2-efe4f9cf7d43','ebe8e234-e065-5b9d-b9ba-b09cccbc3ec6','수리와 폐기 상태 전이','반납 검사에서 이상이 발견되면 자산을 MAINTENANCE로 전환한다. 수리 완료와 기능 점검 통과가 기록된 후에만 AVAILABLE로 복구한다. RETIRED로의 전이는 자산 관리자만 수행하며 폐기 사유를 남긴다. 활성 대여나 미완료 반납 검사가 있으면 폐기를 거부한다. 이미 폐기된 자산은 대여 가능 상태로 되돌릴 수 없다.','{"documentId": "ebe8e234-e065-5b9d-b9ba-b09cccbc3ec6", "chunkId": "dd4f1c1d-2846-5913-aad2-efe4f9cf7d43", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "수리와 폐기 상태 전이", "relatedApis": ["POST /returns/{returnId}/inspection"]}'::jsonb,'[-0.01007881760597229, 0.01565519906580448, -0.013052157126367092, 0.029030023142695427, -0.026622937992215157, -0.015505815856158733, 0.007782205939292908, 0.030353518202900887, -0.017258960753679276, 0.025529958307743073, 0.018521878868341446, -0.0007167718140408397, -0.03528739511966705, 0.029494930058717728, 0.016372792422771454, -0.039498865604400635, 0.0342768058180809, 0.03484805300831795, -0.032335780560970306, 0.0038336629513651133, -0.00923816580325365, 0.0017526925075799227, 0.03195745497941971, 0.015412946231663227, -0.018153786659240723, -0.01529497280716896, -0.012711108662188053, -0.00874166376888752, 0.029614321887493134, 0.045871347188949585, -0.010389949195086956, -0.0383700393140316, -0.030061110854148865, -0.021808475255966187, -0.007773842662572861, -0.012194739654660225, -0.024694565683603287, -0.014264652505517006, -0.02651055157184601, 0.06073789298534393, -0.047490570694208145, -0.03189915046095848, 0.008260797709226608, -0.015074355527758598, 0.010377139784395695, -0.001658285385929048, 0.003678454551845789, -0.021768342703580856, -0.024888526648283005, -0.01405622623860836, -0.030817927792668343, -0.011697216890752316, 0.06691015511751175, -0.02023121528327465, 0.02355308271944523, 0.06981851905584335, 0.012972372584044933, -0.010477294214069843, -0.01154492143541574