INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('97dd0846-eb69-5d26-b10d-321579bdce4e','7cea4fe7-6b00-56c9-be35-3194aeecb923','신청 자격과 중복 대여 제한','재직 상태가 ACTIVE인 임직원만 업무 장비를 신청할 수 있다. 노트북의 활성 대여는 직원당 한 대로 제한한다. 퇴직 예정자는 신규 대여를 신청할 수 없고 기존 장비 반납만 진행한다. 요청자 ID는 로그인 주체에서 결정하며 임의의 다른 직원을 대신하여 신청할 수 없다. 반납 예정일은 신청일보다 뒤여야 한다.','{"documentId": "7cea4fe7-6b00-56c9-be35-3194aeecb923", "chunkId": "97dd0846-eb69-5d26-b10d-321579bdce4e", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "신청 자격과 중복 대여 제한", "relatedApis": ["POST /loans"]}'::jsonb,'[-0.055805400013923645, 0.01652560941874981, -0.039035338908433914, 0.030847515910863876, -0.02625184692442417, -0.014462150633335114, -0.02314254827797413, 0.005201365798711777, 0.031875256448984146, 0.0067613013088703156, 0.01731214113533497, -0.016443753615021706, 0.004157389979809523, 0.006607810501009226, 0.058770742267370224, -0.030616741627454758, -0.0028049880638718605, 0.0017018745420500636, -0.01682598702609539, 0.01192539557814598, 0.012082593515515327, -0.008664035238325596, 0.022196920588612556, 0.03811804950237274, -0.015069222077727318, -0.027967330068349838, -0.029009345918893814, 0.0009976659202948213, 0.0902707576751709, 0.05932172015309334, -0.0004559725057333708, -0.05355602130293846, 0.019649265334010124, -0.03048642911016941, 0.0057313707657158375, -0.012544841505587101, -0.022799858823418617, -0.036873675882816315, -0.031023748219013214, 0.04938278719782829, -0.06529907137155533, -0.0077196634374558926, -0.022931834682822227, -0.03434989973902702, -0.03521643951535225, 0.005726793315261602, -0.030371883884072304, -0.012194078415632248, -0.0323951318860054, -0.03212263062596321, 0.010400030761957169, 0.013639893382787704, 0.07421237975358963, -0.04771825298666954, 0.006749066524207592, 0.08057887107133865, 0.03044806234538555, -0.025591759011149406, -0.057918909937143326, 0.02742752619087696, -0.023