INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('29068730-5e86-57f1-bee2-ffaae1575a08','7cea4fe7-6b00-56c9-be35-3194aeecb923','부서장 승인과 자기 승인 금지','대여 신청은 PENDING_APPROVAL로 생성된다. 요청자 소속 부서의 부서장만 승인할 수 있으며 본인이 작성한 신청은 승인할 수 없다. 자기 승인 대신 상위 조직의 지정 승인자에게 전달한다. 반려 시 사유는 필수다. 취소되었거나 이미 승인된 신청을 다시 승인하면 상태 충돌 오류를 반환한다.','{"documentId": "7cea4fe7-6b00-56c9-be35-3194aeecb923", "chunkId": "29068730-5e86-57f1-bee2-ffaae1575a08", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "부서장 승인과 자기 승인 금지", "relatedApis": ["POST /loans/{loanId}/approve"]}'::jsonb,'[-0.04922710359096527, 0.0059700217097997665, -0.020732734352350235, 0.022211404517292976, -0.006933294702321291, -0.02792016789317131, -0.025200799107551575, -0.008462077006697655, 0.017341386526823044, 0.006916948594152927, -0.020039303228259087, 0.013943610712885857, -0.005963171366602182, 0.024883290752768517, -0.001582166994921863, -0.03819453343749046, -0.004646678455173969, 0.013105461373925209, -0.007634678855538368, 0.006960758473724127, -0.005028313957154751, 0.02161273919045925, 0.03459320217370987, -0.002038528211414814, 0.011582830920815468, -0.010044035501778126, 0.0072508943267166615, 0.049817103892564774, 0.058639105409383774, -0.0026179454289376736, -0.016308868303894997, -0.04094352945685387, 0.034542378038167953, -0.015657024458050728, 0.02172090858221054, -0.03528214991092682, -0.03590632230043411, -0.020166052505373955, -0.023579787462949753, 0.031842805445194244, -0.049925826489925385, -0.009974662214517593, 0.00471851509064436, -0.0551387295126915, -0.020944993942975998, 0.022621015086770058, -0.02539808489382267, -0.021337978541851044, -0.015014499425888062, 0.0066598947159945965, -0.0018689174903556705, 0.03471372276544571, 0.0602986179292202, -0.03246338665485382, -0.012210163287818432, 0.10595229268074036, 0.056420158594846725, 0.015215509571135044, -0.046183012425899506, 0.034949827