INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('4175e617-06be-519d-afbd-b279688fb982','94dcaeab-5ab5-5aff-9af6-8e78cbe0f429','파손 장비의 수리 전환','자산 담당자는 반납 장비의 외관과 작동 상태를 검사한다. 파손 또는 기능 이상이 있으면 검사 결과를 DAMAGED로 기록하고 자산 상태를 MAINTENANCE로 바꾼다. 사진과 파손 설명은 필수이며 정상 재고로 바로 돌릴 수 없다. 이상 없는 장비는 검사 결과 PASSED와 함께 AVAILABLE로 전환한다.','{"documentId": "94dcaeab-5ab5-5aff-9af6-8e78cbe0f429", "chunkId": "4175e617-06be-519d-afbd-b279688fb982", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "파손 장비의 수리 전환", "relatedApis": ["POST /returns/{returnId}/inspection"]}'::jsonb,'[-0.027452418580651283, -0.011876470409333706, -0.024802744388580322, -0.0043551065027713776, -0.027312463149428368, -0.013522111810743809, 0.015591592527925968, 0.023147769272327423, 0.004780595190823078, 0.04018440842628479, 0.004263394977897406, 0.003395186737179756, -0.01608964428305626, 0.03516048192977905, 0.014899034053087234, -0.030477995052933693, 0.02957814931869507, -0.020660411566495895, -0.006999548524618149, 0.0131177743896842, -0.006894256919622421, -0.010545574128627777, 0.05155083164572716, -0.011365563608705997, -0.02010241709649563, 0.001969891367480159, -0.049859825521707535, -0.022895241156220436, 0.03636068105697632, 0.02824881486594677, -0.020045090466737747, -0.039951425045728683, -0.01878853142261505, -0.00017450301675125957, -0.028144823387265205, -0.026411769911646843, -0.04443485289812088, -0.017091678455471992, -0.0140973050147295, 0.059886276721954346, -0.01888899877667427, -0.03459593653678894, 0.003279880853369832, -0.023960715159773827, 0.03424482047557831, 0.00656000804156065, -0.0034498153254389763, -0.030489837750792503, -0.021588802337646484, -0.015617284923791885, -0.050490789115428925, -0.010000181384384632, 0.06440487504005432, -0.020405670627951622, 0.02085079811513424, 0.04518330842256546, -0.026300428435206413, -0.002743162214756012, -0.01759668067097664, 0.033