INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('21da5959-2798-5a63-a9ca-f989cec19f4b','94dcaeab-5ab5-5aff-9af6-8e78cbe0f429','반납 기한과 연체 계산','반납 예정일 다음 날부터 실제 반납 접수일까지 달력 일수로 연체일을 계산한다. 예정일 당일 접수는 연체가 아니다. 반납 검사에 걸린 시간은 임직원 연체일에 추가하지 않는다. 매일 오전 9시에 연체자와 소속 부서장에게 안내한다. 분실 신고가 접수된 경우 연체 안내 대신 분실 처리 절차로 전환한다.','{"documentId": "94dcaeab-5ab5-5aff-9af6-8e78cbe0f429", "chunkId": "21da5959-2798-5a63-a9ca-f989cec19f4b", "documentType": "BUSINESS_RULE", "domain": "IT_ASSET", "version": "1.0.0", "section": "반납 기한과 연체 계산", "relatedApis": ["GET /loans/overdue"]}'::jsonb,'[-0.045412324368953705, 0.005676575005054474, -0.018536565825343132, 0.015388408675789833, -0.03593558445572853, -0.03857388347387314, -0.0010759106371551752, 0.027991680428385735, 0.0031399179715663195, -0.0005931370542384684, -0.0017380992649123073, -0.010851298458874226, 0.0024560519959777594, 0.04995276778936386, -0.024553202092647552, -0.004126672632992268, 0.005156510975211859, -0.029252123087644577, 0.017612483352422714, -0.003879647236317396, 0.03653458505868912, -0.01142111700028181, 0.048176657408475876, -0.005185503512620926, -0.009455048479139805, -0.019999945536255836, -0.0007083870586939156, 0.009851457551121712, 0.06691867858171463, 0.01832968182861805, 0.0011566681787371635, -0.03111426904797554, 0.040433503687381744, -5.207191861700267e-06, -0.009451189078390598, -0.008410981856286526, -0.004413215909153223, -0.0029155544470995665, -0.017234746366739273, 0.07450272887945175, 0.011304294690489769, -0.03473616763949394, 0.007585116196423769, 0.0027316734194755554, 0.04388465732336044, 0.01130816899240017, -0.03528304398059845, -0.03267449885606766, -0.011681734584271908, -0.008395113982260227, -0.00607334217056632, -0.010553311556577682, 0.0911770910024643, -0.018279626965522766, 0.0070731802843511105, 0.050547387450933456, -0.017062002792954445, -0.016150929033756256, -0.024782618507742882, 0.003195144236087799,