INSERT INTO rag.knowledge_chunk(id,document_id,section,content,metadata,embedding,embedding_profile_id,embedding_dimensions) VALUES ('d10c2901-6178-56c5-a019-c45bb1ce5520','34b91c10-3bd5-547e-97c2-18641d80eb14','대여 승인 권한 테스트','서로 다른 두 직원과 부서장을 합성 계정으로 준비한다. 부서장은 같은 부서 직원의 신청을 승인할 수 있어야 한다. 일반 직원, 타 부서 부서장, 신청자 본인의 승인은 HTTP 403으로 거부되어야 한다. 거부된 요청은 신청 상태와 자산 상태를 변경하지 않아야 한다. 자기 승인 오류 코드는 SELF_APPROVAL_FORBIDDEN으로 확인한다.','{"documentId": "34b91c10-3bd5-547e-97c2-18641d80eb14", "chunkId": "d10c2901-6178-56c5-a019-c45bb1ce5520", "documentType": "TEST_GUIDE", "domain": "IT_ASSET", "version": "1.0.0", "section": "대여 승인 권한 테스트", "relatedApis": ["POST /loans/{loanId}/approve"]}'::jsonb,'[-0.031056512147188187, 0.0148067781701684, -0.029854951426386833, -0.0009021920850500464, 0.0019186162389814854, -0.0160172488540411, -0.00012894543760921806, -0.034491490572690964, 0.021649226546287537, 0.01012567151337862, -0.029620524495840073, -0.008568339049816132, 0.0019323376473039389, -0.004523152485489845, -0.0026783260982483625, -0.05354568362236023, -0.0166204571723938, -0.00971404928714037, -0.03087206743657589, -0.011561844497919083, -0.028240438550710678, 0.01773548312485218, 0.017030727118253708, -0.0032312367111444473, -0.0010837159352377057, 0.0014762214850634336, 0.0011806273832917213, 0.017619958147406578, 0.03612484410405159, 0.02461143210530281, 0.0016255779191851616, -0.0637345090508461, 0.050835441797971725, -0.021888943389058113, 0.0094262370839715, -0.01273565087467432, -0.018312234431505203, -0.0196857750415802, -0.023053135722875595, 0.018920574337244034, -0.03962332010269165, 0.009868203662335873, 0.008314180187880993, -0.07075069844722748, -0.015952114015817642, -0.0030038529075682163, 0.013886318542063236, -0.026598112657666206, -0.036931052803993225, 0.016256071627140045, -0.011815371923148632, 0.0012461419682949781, 0.07934597879648209, -0.025745533406734467, -0.00043408371857367456, 0.06922274082899094, 0.05705302953720093, 0.03467434272170067, -0.046110354363